-- All existing GameResult rows are seed/test data (see prisma/seed.ts) and
-- will be regenerated by the next seed run — deleting first avoids a NOT
-- NULL violation on the new columns below, which have no default.
DELETE FROM "GameResult";

-- AlterTable
ALTER TABLE "GameResult" DROP COLUMN "cognitiveFlexibility",
DROP COLUMN "prosociality",
DROP COLUMN "selectiveAttention",
ADD COLUMN     "collaborationMindset" INTEGER NOT NULL,
ADD COLUMN     "criticalThinking" INTEGER NOT NULL,
ADD COLUMN     "decisionMakingUnderPressure" INTEGER NOT NULL,
ADD COLUMN     "learningAgility" INTEGER NOT NULL,
ADD COLUMN     "overallIndex" INTEGER NOT NULL,
ADD COLUMN     "resilienceAndAdaptability" INTEGER NOT NULL;
